package ru.mcsa.bukkit;
import java.util.*;import org.bukkit.*;import org.bukkit.enchantments.*;import org.bukkit.inventory.*;
public final class EnchantEvents {
 private static final String[] names={"aqua_affinity","bane_of_arthropods","binding_curse","blast_protection","breach","channeling","density","depth_strider","efficiency","feather_falling","fire_aspect","fire_protection","flame","fortune","frost_walker","impaling","infinity","knockback","looting","loyalty","luck_of_the_sea","lunge","lure","mending","multishot","piercing","power","projectile_protection","protection","punch","quick_charge","respiration","riptide","sharpness","silk_touch","smite","soul_speed","sweeping_edge","swift_sneak","thorns","unbreaking","vanishing_curse","wind_burst"};
 private static Enchantment enchant(int id){return id<0||id>=names.length?null:Enchantment.getByKey(NamespacedKey.minecraft(names[id]));}
 private static ItemStack item(String[] a,int at){return ItemStack.fromHost(Material.matchMaterial(a[at]),Integer.parseInt(a[at+1]),a[at+2]);}
 public static void prepare(org.bukkit.entity.Player player,String[] a){ItemStack item=item(a,9);int[] props=new int[10];for(int i=0;i<10;i++)props[i]=Integer.parseInt(a[12+i]);EnchantmentOffer[] offers=new EnchantmentOffer[3];for(int i=0;i<3;i++){Enchantment type=enchant(props[4+i]);if(props[i]>0&&type!=null&&props[7+i]>0)offers[i]=new EnchantmentOffer(type,props[7+i],props[i]);}
  org.bukkit.event.enchantment.PrepareItemEnchantEvent event=new org.bukkit.event.enchantment.PrepareItemEnchantEvent(player,item,offers);RuntimeState.fire(event);if(event.isCancelled()){Host.call(22,"");return;}for(int i=0;i<3;i++){EnchantmentOffer offer=offers[i];if(offer==null){props[i]=0;props[4+i]=-1;props[7+i]=-1;}else {props[i]=offer.getCost();props[4+i]=java.util.Arrays.asList(names).indexOf(offer.getEnchantment().getKey().getKey());props[7+i]=offer.getEnchantmentLevel();}}StringBuilder result=new StringBuilder();for(int value:props)result.append(value).append(' ');Host.call(22,result.toString());
 }
 public static void enchant(org.bukkit.entity.Player player,String[] a){ItemStack input=item(a,9),output=item(a,12);java.util.Map<Enchantment,Integer> rolled=output.getItemMeta() instanceof org.bukkit.inventory.meta.EnchantmentStorageMeta?((org.bukkit.inventory.meta.EnchantmentStorageMeta)output.getItemMeta()).getStoredEnchants():output.getEnchantments();
  org.bukkit.event.enchantment.EnchantItemEvent event=new org.bukkit.event.enchantment.EnchantItemEvent(player,input,new LinkedHashMap<>(rolled),Integer.parseInt(a[16]),Integer.parseInt(a[15]),a[17].isEmpty()?null:Enchantment.getByKey(NamespacedKey.minecraft(a[17])),Integer.parseInt(a[18]));RuntimeState.fire(event);if(event.isCancelled()){Host.call(22,"");return;}
  Map<String,Object> metadata=Yaml.parse(input.metadata());metadata.remove("stored");metadata.remove("enchants");Map<String,Object> enchants=new LinkedHashMap<>();for(Map.Entry<Enchantment,Integer> entry:event.getEnchantsToAdd().entrySet())enchants.put(entry.getKey().getKey().toString(),entry.getValue());metadata.put(output.getType()==Material.ENCHANTED_BOOK?"stored":"enchants",enchants);Host.call(22,Ascii.lower(output.getType().name())+"\n"+input.getAmount()+"\n"+Yaml.write(metadata));
 }
}
